let pendingWebsiteImport=null,websiteRequest=null,websiteToken=null,websiteTargetCategory=v.type;
const websiteStart=startScreen,websiteField=field,websitePackets=packetTools,websiteRender=render,websiteBind=bindVendor;
startScreen=function(){return header('Bring what you already have.<br><em>We’ll help finish the gaps.</em>','Read your real website, review what the sources support, and use the assistant to fill what is missing.')+`<div class="split"><section class="panel"><span class="eyebrow">LIVE WEBSITE IMPORT</span><h2 style="margin-top:12px">Start with your public business pages.</h2><label for="web-category" style="margin-top:24px">Category for the new draft</label><select id="web-category">${Object.keys(categories).map(type=>`<option value="${type}" ${type===websiteTargetCategory?'selected':''}>${type==='Caterer'?'Catering':type==='DJ'?'DJ & entertainment':type}</option>`).join('')}</select><label for="source-url" style="margin-top:20px">Your website or portfolio</label><input id="source-url" type="url" value="${safe(v.sourceUrl||'')}" placeholder="https://yourbusiness.com"><p class="helper">Up to five public HTML pages · One OpenAI extraction request · PDFs, images, and pages requiring browser rendering are not read.</p><div class="start-actions"><button class="primary" data-action="import">Read website & draft →</button><button class="text" data-web="example">Use Bittersweet Catering URL</button></div><p class="small" style="margin-top:14px">You review the returned answers before they replace your current draft. Published listings stay unchanged.</p><hr class="divider"><h3>Finish the gaps through conversation.</h3><p style="margin:10px 0 18px">The assistant can help with your current draft. Speak or type, then review each proposed change.</p><button class="secondary" data-action="voice">Help me finish my profile →</button><details class="requirements-disclosure"><summary>Other ways to try the demo</summary><p><button class="text" data-web="sample">Use a fictional ${websiteTargetCategory.toLowerCase()} sample</button></p><p class="small">The fictional sample import is simulated and labeled separately.</p><button class="text" data-method="manual">Enter everything myself instead</button>${v.method==='manual'?'<p class="small">The blank manual intake has the same 58-answer requirements.</p><button class="secondary" data-depth="manual-start">Begin blank manual intake →</button>':''}</details></section><aside class="note"><span class="eyebrow">REAL SOURCES. REVIEWABLE ANSWERS.</span><h2 style="margin-top:16px">See what your website actually says.</h2><ol><li><b>Read public pages</b><p>We retrieve the pages and show which URLs were read.</p></li><li><b>Check the evidence</b><p>Each proposed answer includes its source excerpt.</p></li><li><b>Finish the missing details</b><p>Unpublished pricing, contract terms, and insurance stay blank.</p></li></ol><p class="small">Live imports use the local service on this computer. No sample data is substituted if retrieval fails.</p></aside></div>`};
field=function(key,label,options={}){let html=websiteField(key,label,options);const evidence=v.evidence[key];if(evidence?.live&&validUrl(evidence.url))html=html.replace('</details>',`<p><a href="${safe(evidence.url)}" target="_blank" rel="noopener">Open original website page ↗</a></p><span class="small">${evidence.provided?'Website URL supplied by you':'Retrieved '+safe(new Date(evidence.retrievedAt).toLocaleString())}</span></details>`);return html}
packetTools=function(){if(!v.liveImport)return websitePackets();return `<section class="panel packet-tools"><span class="eyebrow">REAL WEBSITE SOURCES</span><h3>What we actually read</h3><ul class="live-source-list">${v.liveImport.sources.map(source=>`<li><a href="${safe(source.url)}" target="_blank" rel="noopener">${safe(source.title)} ↗</a></li>`).join('')}</ul><p class="small">Retrieved ${safe(new Date(v.liveImport.retrievedAt).toLocaleString())}. ${v.liveImport.model} generated the suggestions; you chose which to apply.</p>${v.liveImport.notes.map(note=>`<p class="small">${safe(note)}</p>`).join('')}</section>`}
async function importGateway(route,body,token){const response=await fetch('http://127.0.0.1:4180/api/voice/'+route,{method:body===undefined?'GET':'POST',headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(token?{Authorization:'Bearer '+token}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(route==='import'?110000:6000)});const data=await response.json();if(!response.ok){if(response.status===401)websiteToken=null;throw Error(data.error||'The website import did not complete.');}return data}
const fictionalImport=importSample;importSample=async function(){if(v.sample&&v.sourceUrl===categories[websiteTargetCategory].website){const previous=JSON.parse(JSON.stringify(v));v.type=websiteTargetCategory;v.data={};v.evidence={};delete v.liveImport;await fictionalImport();if(v.data.name!==categories[v.type].name)v=previous;save();render();return}let input;try{input=new URL(v.sourceUrl||'');if(input.protocol!=='https:')throw Error()}catch{error='Enter a public https:// website address, or choose the fictional sample.';render();return}if(busy)return;busy=true;error='';render();q('.workspace').innerHTML=header('Reading your real website.','Retrieving public pages and drafting supported answers with OpenAI.')+`<section class="panel loading" role="status"><div class="spinner"></div><h2>Your existing information, organized.</h2><p>Reading up to five public pages, then generating source-backed suggestions.</p><p class="small">One extraction request · No automatic retries · This may take about a minute.</p></section>`;try{const health=await importGateway('status');if(!health.ready||!health.importReady)throw Error('Restart the local voice launcher to enable live website import.');if(!websiteRequest||websiteRequest.url!==input.href||websiteRequest.category!==websiteTargetCategory)websiteRequest={requestId:crypto.randomUUID(),url:input.href,category:websiteTargetCategory};if(!websiteToken)websiteToken=(await importGateway('connect',{})).token;pendingWebsiteImport=await importGateway('import',websiteRequest,websiteToken);page='website-review';busy=false;render();window.scrollTo(0,0)}catch(problem){busy=false;page='setup';error=problem.name==='TypeError'||problem.name==='TimeoutError'?'The local import service could not be reached or timed out. Keep the launcher running and try the local experience at http://127.0.0.1:4180. No sample data was substituted.':problem.message;render()}}
function websiteReview(){const result=pendingWebsiteImport,labels=BubsVendorContract.labelsForCategory(result.category);return header('Here’s what your website supports.','Review real source evidence before adding these answers to your onboarding draft.')+`<div class="banner"><b>Live website import · ${result.fields.length} supported suggestions · ${58-result.fields.length} answers still missing</b><p>${safe(result.summary)}</p><p class="small">${result.sources.length} pages read · ${safe(result.model)} · ${safe(new Date(result.retrievedAt).toLocaleString())}${result.cached?' · Recovered cached result; no additional extraction request':''}</p></div><div class="live-review-layout"><section class="panel"><h2>Choose what to use</h2><p class="small">Applying selected answers starts a new draft. Any previously published listing stays unchanged. The business has not approved this research draft.</p>${result.fields.map((item,index)=>{const source=result.sources.find(s=>s.id===item.sourceId);return `<article class="live-proposal"><div class="checkrow"><input type="checkbox" id="web-answer-${index}" data-web-answer="${index}" checked><label for="web-answer-${index}">${safe(labels[item.field])}</label></div><strong>${safe(item.value)}</strong><blockquote>${safe(item.quote)}</blockquote><a class="small" href="${safe(source.url)}" target="_blank" rel="noopener">${safe(source.title)} ↗</a><span class="badge">${safe(item.scope.replaceAll('-',' '))}</span></article>`}).join('')||'<p>No sufficiently supported fields were found. Your existing draft was not changed.</p>'}<div class="actions"><button class="text" data-web="cancel">← Keep my existing draft</button><button class="primary" data-web="apply" ${result.fields.length?'':'disabled'}>Use selected answers →</button></div></section><aside class="depth-aside"><section class="panel"><span class="eyebrow">RETRIEVAL RECEIPT</span><h3>Pages actually read</h3><ul class="live-source-list">${result.sources.map(source=>`<li><a href="${safe(source.url)}" target="_blank" rel="noopener">${safe(source.title)} ↗</a>${source.truncated?'<small>Excerpt limited by pilot size cap</small>':''}</li>`).join('')}</ul><p class="small">Linked PDFs and images were not read. Pages can change after this retrieval.</p></section><section class="panel"><h3>What still needs you</h3>${result.notes.map(note=>`<p class="small">${safe(note)}</p>`).join('')}<ul class="checklist">${result.missing.slice(0,10).map(key=>`<li>○ ${safe(labels[key])}</li>`).join('')}<li>Use the assistant or your business records to fill the remaining gaps.</li></ul>${result.warnings.length?`<details><summary>Retrieval limitations</summary>${result.warnings.map(warning=>`<p class="small">${safe(warning)}</p>`).join('')}</details>`:''}${result.rejections.length?`<p class="small">${result.rejections.length} unsupported or out-of-scope suggestions were withheld.</p>`:''}</section></aside></div>`}
render=function(){if(page==='website-review'&&pendingWebsiteImport){q('#vendor-app').innerHTML=shell(websiteReview());bindVendor()}else websiteRender()};
bindVendor=function(){websiteBind();if(q('#web-category'))q('#web-category').onchange=e=>{websiteTargetCategory=e.target.value;if(!Object.values(v.data).some(Boolean))v.type=websiteTargetCategory;render()};document.querySelectorAll('[data-depth="manual-start"]').forEach(button=>{const old=button.onclick;button.onclick=()=>{v.type=websiteTargetCategory;delete v.liveImport;old()}});document.querySelectorAll('[data-stage]').forEach(button=>{const previous=button.onclick;button.onclick=()=>{if(page==='website-review')page='setup';previous()}});document.querySelectorAll('[data-web]').forEach(button=>button.onclick=()=>{if(button.dataset.web==='example'){v.sourceUrl='https://www.bittersweetcatering.com/';websiteTargetCategory='Caterer';if(!Object.values(v.data).some(Boolean))v.type=websiteTargetCategory;v.sample=false;save();render()}if(button.dataset.web==='sample'){v.sourceUrl=categories[websiteTargetCategory].website;v.sample=true;save();render()}if(button.dataset.web==='cancel'){page='setup';render()}if(button.dataset.web==='apply'){const result=pendingWebsiteImport,selected=[...document.querySelectorAll('[data-web-answer]:checked')].map(input=>result.fields[Number(input.dataset.webAnswer)]);if(!selected.length){notify('Select at least one supported answer to use.');return}v.data={};v.evidence={};v.type=result.category;for(const item of selected){const source=result.sources.find(s=>s.id===item.sourceId);v.data[item.field]=item.value;v.evidence[item.field]={value:item.value,quote:item.quote,label:'Live website · '+source.title,url:source.url,retrievedAt:source.retrievedAt,live:true}}if(!v.data.website){v.data.website=result.url;v.evidence.website={value:result.url,quote:'Website URL supplied for this import: '+result.url,label:'Provided website URL',url:result.url,retrievedAt:result.retrievedAt,live:true,provided:true}}v.liveImport={model:result.model,retrievedAt:result.retrievedAt,sources:result.sources.map(({id,url,title,retrievedAt,truncated})=>({id,url,title,retrievedAt,truncated})),notes:result.notes,warnings:result.warnings};v.sourceUrl=result.url;v.sample=false;v.method='live-website';v.sectionReviews={};v.confirmedPrice=false;v.confirmedDelivery=false;v.reviewed=false;v.consent=false;v.photo='';v.insuranceName='';insuranceFile=null;page='setup';save();navigate(1);notify(`${selected.length} supported website answers applied. Missing details remain blank.`)}})};
render();
